-- Provenance keys (mirrors FAA ingest style)
MERGE INTO global_configuration t USING (SELECT 'adsbx.ingest.sample_date' AS config_key FROM dual) s ON (t.config_key = s.config_key) WHEN MATCHED THEN UPDATE SET config_value = '2026-06-01', updated_at = SYSTIMESTAMP WHEN NOT MATCHED THEN INSERT (config_key, config_value, description) VALUES ('adsbx.ingest.sample_date', '2026-06-01', 'ADS-B Exchange free sample day used for corridor ops baseline');
MERGE INTO global_configuration t USING (SELECT 'adsbx.ingest.overlay' AS config_key FROM dual) s ON (t.config_key = s.config_key) WHEN MATCHED THEN UPDATE SET config_value = '125', updated_at = SYSTIMESTAMP WHEN NOT MATCHED THEN INSERT (config_key, config_value, description) VALUES ('adsbx.ingest.overlay', '125', 'Applied ADSBX ops overlay seed script');

